from AlgorithmImports import *

from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: (
                universe.IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
            )
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket = None

        self.held_symbol = None
        self.entry_order = None
        self.entry_price = None
        self.exit_order = None
        self.expiration_liquidation_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if (
            self.held_symbol is not None
            and today >= self.held_symbol.ID.Date.date()
        ):
            self.expiration_liquidation_date = today
            self._liquidate_option("expiration-day liquidation")
            return

        if self.held_symbol is not None:
            self._check_exit_conditions(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._accept_minute_bar(bar, slice)

    def _accept_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        t = minute_bar.Time

        if (
            t.hour < 9
            or (t.hour == 9 and t.minute < 30)
            or t.hour >= 16
        ):
            return

        start = datetime(
            t.year,
            t.month,
            t.day,
            t.hour,
            (t.minute // 5) * 5,
            0
        )

        if self.bucket_start is not None and start != self.bucket_start:
            self._complete_five_minute_bar(slice)
            self.bucket_start = None
            self.bucket = None

        if self.bucket_start is None:
            self.bucket_start = start
            self.bucket = {
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": minute_bar.Volume
            }
        else:
            self.bucket["high"] = max(
                self.bucket["high"],
                minute_bar.High
            )
            self.bucket["low"] = min(
                self.bucket["low"],
                minute_bar.Low
            )
            self.bucket["close"] = minute_bar.Close
            self.bucket["volume"] += minute_bar.Volume

    def _complete_five_minute_bar(self, slice: Slice):
        if self.bucket is None or self.bucket_start is None:
            return

        end_time = self.bucket_start + timedelta(minutes=5)
        close = float(self.bucket["close"])

        self.closes.append(close)
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_clock = end_time.time()
        if (
            bullish
            and datetime(1900, 1, 1, 9, 45).time()
            <= end_clock
            <= datetime(1900, 1, 1, 14, 30).time()
        ):
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None or self.entry_order is not None:
            return

        if self.expiration_liquidation_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(
                "Skipped call selection: no option chain in current Slice"
            )
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(
                "Skipped call selection: no expiration at least "
                "7 calendar days out"
            )
            return

        expiry = expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid current SPY price")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no qualifying call "
                "at selected expiration"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_order = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def _check_exit_conditions(self, slice: Slice):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._liquidate_option("expiration-eve time stop")
            return

        if self.exit_order is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_order is not None:
            if self.exit_order.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self.exit_order.Cancel("Replaced by " + reason)

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity != 0:
            self.exit_order = self.MarketOrder(
                self.held_symbol,
                -quantity
            )
            self.Debug(
                "Exit submitted ({0}): {1}".format(
                    reason,
                    self.held_symbol
                )
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order is not None
            and order_event.OrderId == self.entry_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order = None

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(
                    "Entry order did not fill: {0}".format(
                        order_event.Status
                    )
                )
                self.entry_order = None

            return

        if (
            self.exit_order is not None
            and order_event.OrderId == self.exit_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

                self.exit_order = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order = None

    def OnAssignmentOrderEvent(
        self,
        assignment_event: AssignmentOrderEvent
    ):
        self.Debug(
            "Unexpected option exercise or assignment: {0}".format(
                assignment_event
            )
        )
