```python
from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.minute_buckets = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_submitted = False
        self.expiration_processing_date = None

    def OnData(self, slice):
        current_date = self.Time.date()

        # Expiration-day processing takes precedence over all other actions.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_processing_date = current_date
                self.SubmitExit("expiration-day liquidation")
            elif self.IsExpirationEve(current_date, expiry_date):
                if self.Time.time() >= time(15, 45):
                    self.SubmitExit("expiration-eve time stop")

            self.EvaluateProfitTarget(slice)

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None:
            return

        if self.expiration_processing_date == current_date:
            return

        bar = None
        if self.spy in slice.Bars:
            bar = slice.Bars[self.spy]

        if bar is None:
            return

        self.ProcessMinuteBar(bar, slice)

    def ProcessMinuteBar(self, minute_bar, slice):
        end_time = minute_bar.EndTime
        bar_date = end_time.date()
        bar_time = end_time.time()

        # Regular session only. End times are aligned so the first bar ends at 09:35.
        if bar_time <= time(9, 30) or bar_time > time(16, 0):
            return

        end_minute = end_time.hour * 60 + end_time.minute
        bucket_end_minute = ((end_minute + 4) // 5) * 5
        bucket_end = time(bucket_end_minute // 60, bucket_end_minute % 60)

        if bucket_end < time(9, 35) or bucket_end > time(16, 0):
            return

        key = (bar_date, bucket_end)

        if key not in self.minute_buckets:
            self.minute_buckets[key] = {
                "count": 0,
                "last_close": None,
                "minutes": set()
            }

        bucket = self.minute_buckets[key]
        minute_key = (bar_date, end_time.hour, end_time.minute)

        if minute_key in bucket["minutes"]:
            return

        bucket["minutes"].add(minute_key)
        bucket["count"] += 1
        bucket["last_close"] = float(minute_bar.Close)

        # A completed five-minute interval must contain all five minute bars.
        if end_time.minute != bucket_end.minute or bucket["count"] != 5:
            return

        close = bucket["last_close"]
        del self.minute_buckets[key]

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        crossover_time = end_time.time()

        if not (time(9, 45) <= crossover_time <= time(14, 30)):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self.TryEnterCall(slice, close)

    def TryEnterCall(self, slice, spy_price):
        if self.entry_ticket is not None or self.held_symbol is not None:
            return

        chain = None

        if self.option_symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option_symbol]
        else:
            for candidate in slice.OptionChains.Values:
                if candidate.Symbol == self.option_symbol:
                    chain = candidate
                    break

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))

        selected = candidates[0]
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def EvaluateProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_submitted:
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]

        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_submitted:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0:
            return

        # Cancel any other open orders for the held contract before exiting.
        self.Transactions.CancelOpenOrders(
            self.held_symbol,
            "canceling other exit orders"
        )

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_submitted = True

        self.Debug(
            "Exit submitted: {0}, reason={1}".format(
                self.held_symbol,
                reason
            )
        )

    def IsExpirationEve(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate > current_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate -= timedelta(days=1)

        while candidate >= expiry_date:
            candidate -= timedelta(days=1)

        previous_trading_day = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        return current_date == previous_trading_day

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
