    def _evaluate_minute_exit(self, slice: Slice):
        if self._held_option is None:
            return

        if self._exit_order_is_open():
            return

        current_date = self.Time.date()

        if (
            self._time_stop_date == current_date
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("Expiration-eve 15:45 time stop")
            return

        if not slice.QuoteBars.ContainsKey(self._held_option):
            return

        quote = slice.QuoteBars[self._held_option]

        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2

        if (
            self._entry_price is not None
            and midpoint >= self._entry_price * 1.50
        ):
            self._submit_exit("50 percent option profit target")

    def _process_expiration(self, current_date):
        if self._held_option is None:
            return

        expiry_date = self.Securities[self._held_option].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._expiration_block_date = current_date

            if not self._exit_order_is_open():
                self._submit_exit("Expiration processing liquidation")

    def _submit_exit(self, tag):
        if self._held_option is None:
            return

        if self._exit_order_is_open():
            return

        quantity = self.Portfolio[self._held_option].Quantity

        if quantity == 0:
            self._clear_position_state()
            return

        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity,
            tag=tag
        )

    def _select_option(self, slice, current_date, spy_price):
        if slice.OptionChains is None:
            return None

        minimum_expiry = current_date + timedelta(days=7)
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()

                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike < spy_price * 1.01:
                    continue

                contracts.append(contract)

        if not contracts:
            return None

        nearest_expiry = min(c.Expiry.date() for c in contracts)

        eligible = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiry
        ]

        eligible.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        return eligible[0]

    def _eligible_entry_time(self, bar_end):
        local_time = bar_end.time()
        return (
            local_time >= self.Time.replace(
                hour=9, minute=45, second=0, microsecond=0
            ).time()
            and local_time <= self.Time.replace(
                hour=14, minute=30, second=0, microsecond=0
            ).time()
        )

    def _is_regular_session_minute(self, minute_start):
        return (
            minute_start.weekday() < 5
            and minute_start.time() >= self.Time.replace(
                hour=9, minute=30, second=0, microsecond=0
            ).time()
            and minute_start.time() < self.Time.replace(
                hour=16, minute=0, second=0, microsecond=0
            ).time()
        )

    def _bucket_start(self, minute_start):
        session_start = minute_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        elapsed_minutes = int(
            (minute_start - session_start).total_seconds() // 60
        )
        return session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

    def _previous_trading_day(self, expiry_date):
        date = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return date.date()

    def _entry_order_is_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _clear_position_state(self):
        self._held_option = None
        self._entry_price = None
        self._time_stop_date = None
        self._exit_ticket = None
