        self.entry_symbol = None
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Expiration protection is processed before any new-entry logic.
        if self.held_symbol is not None:
            expiration = self._expiration_date(self.held_symbol)

            if expiration is not None and today >= expiration:
                self.no_entry_date = today
                self._liquidate_held_option("expiration protection")

            else:
                self._evaluate_time_stop(today)
                self._evaluate_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

    def _process_spy_minute(self, minute_bar: TradeBar, slice: Slice):
        start_time = minute_bar.Time
        local_date = start_time.date()
        local_time = start_time.time()

        # Regular-session SPY bars only.
        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        bucket_minute = (local_time.minute // 5) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            local_time.hour,
            bucket_minute
        )

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_date = local_date
            self.bucket_bars = {}

        # Duplicate or out-of-order minute data cannot complete a valid bar.
        minute_key = start_time.replace(second=0, microsecond=0)
        self.bucket_bars[minute_key] = minute_bar

        expected_minutes = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

