        if self.no_entry_date == algorithm_date:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Quantity != 0:
                return

        # Enforce one option position at a time, including unexpected holdings.
        for security in self.Securities.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and self.Portfolio[security.Symbol].Quantity != 0
            ):
                return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: current Slice has no option chain.")
            return

        minimum_expiration = algorithm_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiration
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        strike_candidates = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Strike >= strike_floor
            )
        ]

        if not strike_candidates:
            self.Debug(
                "Skipped call selection: no qualifying call at selected expiration."
            )
            return

        selected_contract = min(
            strike_candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_symbol = selected_contract.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish 5-minute crossover call entry"
        )

        self.Debug(
            "Submitted call entry: {0}, expiration {1}, strike {2}".format(
                self.entry_symbol,
                selected_expiration,
                selected_contract.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        quote_bar = slice.QuoteBars.get(self.held_symbol)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_held_option("50% profit target")

    def _evaluate_time_stop(self, today: date):
        if self.held_symbol is None:
            return

        expiration = self._expiration_date(self.held_symbol)
        if expiration is None:
            return

        previous_trading_day = self._previous_trading_day(expiration)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._liquidate_held_option("expiration-minus-one-trading-day stop")

    def _liquidate_held_option(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit: " + reason)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Submitted option exit: {0}, quantity {1}, reason: {2}".format(
                self.held_symbol,
                quantity,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option exercise or assignment: {0}".format(
                    order_event
                )
            )
            self.no_entry_date = self.Time.date()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_symbol = self.entry_symbol

                self.Debug(
                    "Call entry filled: {0}, fill price {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Call entry did not fill: {0}".format(order_event))
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Call exit filled: {0}, fill price {1}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_symbol = None
            self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected option exercise or assignment handling: {0}".format(
                assignment_event
            )
        )
        self.no_entry_date = self.Time.date()

    def _expiration_date(self, symbol: Symbol):
        try:
            return symbol.ID.Date.date()
        except Exception:
            return None

    def _previous_trading_day(self, expiration_date: date) -> date:
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiration_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_is_open(self, ticket: OrderTicket) -> bool:
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
