from QuantConnect import Resolution, OptionRight, OrderStatus
from QuantConnect.Algorithm import QCAlgorithm


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(0)  # Raw

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                      .Strikes(-1000, 1000)
                      .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_close = None
        self.last_minute_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnData(self, slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._process_time_stop(current_date)
        self._process_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        bar_end, close = completed_bar
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        fast_now = sum(self.fast_window) / 5.0
        slow_now = sum(self.slow_window) / 20.0

        if len(self.fast_window) < 2 or len(self.slow_window) < 2:
            return

        fast_previous = (
            sum(list(self.fast_window)[:-1]) / 5.0
            if len(self.fast_window) == 5
            else None
        )
        slow_previous = (
            sum(list(self.slow_window)[:-1]) / 20.0
            if len(self.slow_window) == 20
            else None
        )

        if fast_previous is None or slow_previous is None:
            return

        bullish_cross = (
            fast_previous <= slow_previous
            and fast_now > slow_now
        )

        if bullish_cross:
            self._try_enter(slice, close, current_date)

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option exercise or assignment: "
                + str(order_event.Symbol)
            )

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled,
                ):
                    self.held_symbol = order_event.Symbol
                    self.entry_fill_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {} @ {:.4f}".format(
                            order_event.Symbol,
                            order_event.FillPrice,
                        )
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    if self.held_symbol is None:
                        self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} @ {:.4f}".format(
                            order_event.Symbol,
                            order_event.FillPrice,
                        )
                    )
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_fill_price = None
                        self.exit_ticket = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

    def _update_five_minute_bar(self, minute_bar):
        end = minute_bar.EndTime
        current_date = end.date()

        if not (time(9, 30) < end.time() <= time(16, 0)):
            return None

        bucket_minute = ((end.minute + 4) // 5) * 5
        bucket_end = datetime(
            end.year,
            end.month,
            end.day,
            end.hour,
            bucket_minute,
        )

        if self.bucket_end is None or bucket_end != self.bucket_end:
            completed = None

            if (
                self.bucket_end is not None
                and self.bucket_valid
                and self.bucket_count == 5
            ):
                completed = (self.bucket_end, self.bucket_close)

            self.bucket_date = current_date
            self.bucket_end = bucket_end
            self.bucket_count = 1
            self.bucket_valid = True
            self.bucket_close = minute_bar.Close
            self.last_minute_end = end

            if completed is not None:
                self.fast_window.append(completed[1])
                self.slow_window.append(completed[1])
                return completed

            return None

        expected_end = self.last_minute_end + timedelta(minutes=1)
        if end != expected_end:
            self.bucket_valid = False

        self.bucket_count += 1
        self.bucket_close = minute_bar.Close
        self.last_minute_end = end

        return None

    def _try_enter(self, slice, spy_price, current_date):
