        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_filled_quantity = 0
        self.entry_cost = 0

        self.expiration_date = None
        self.blocked_entry_date = None

    def OnData(self, data):
        now = self.Time
        today = now.date()

        if self.held_symbol is not None:
            if self.expiration_date == today:
                self.blocked_entry_date = today
                self._submit_exit("expiration-day liquidation")
            else:
                self._evaluate_exits(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, now)

    def _process_minute_bar(self, bar, now):
        local_minute = now.replace(second=0, microsecond=0)
        minute_number = local_minute.hour * 60 + local_minute.minute

        # Regular session only: 09:30 through 15:59.
        if minute_number < 570 or minute_number >= 960:
            return

        bucket_minute = 570 + ((minute_number - 570) // 5) * 5
        bucket_start = local_minute.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self._complete_bucket(self.bucket_start)
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        # Duplicate timestamps are ignored.
        self.bucket_bars[local_minute] = bar

        if len(self.bucket_bars) == 5:
            expected = {
                self.bucket_start + timedelta(minutes=i)
                for i in range(5)
            }
            if set(self.bucket_bars.keys()) == expected:
                self._complete_bucket(self.bucket_start)

            self.bucket_start = None
            self.bucket_bars = {}

    def _complete_bucket(self, bucket_start):
        if len(self.bucket_bars) != 5:
            return

        expected = {
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        }
        if set(self.bucket_bars.keys()) != expected:
            return

        bars = [
            self.bucket_bars[bucket_start + timedelta(minutes=i)]
            for i in range(5)
        ]

        close = bars[-1].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

