class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast = SimpleMovingAverage(self.fast_period)
        self.slow = SimpleMovingAverage(self.slow_period)

        self._minute_bars = {}
        self._current_bucket_end = None
        self._previous_fast = None
        self._previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_tickets = []
        self.expiration_date = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._evaluate_exits(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        self._consume_minute_bar(bar, slice)

    def _consume_minute_bar(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        if local_end.time() < datetime.time(9, 31):
            return
        if local_end.time() > datetime.time(16, 0):
            return

        bucket_end = local_end.replace(
            minute=(local_end.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._current_bucket_end != bucket_end:
            self._minute_bars = {}
            self._current_bucket_end = bucket_end

        self._minute_bars[local_end] = bar

        if local_end != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._minute_bars for t in expected_times):
            self._minute_bars = {}
            return

        bars = [self._minute_bars[t] for t in reversed(expected_times)]
        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars)
        )

        self._minute_bars = {}
        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_crossover = (
            self._previous_fast is not None and
            self._previous_slow is not None and
            self._previous_fast <= self._previous_slow and
            current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        bar_end = bar.EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = (
            datetime.time(9, 45) <= bar_end.time() <= datetime.time(14, 30)
        )

        if not bullish_crossover or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self._entry_order_open() or self._option_holding_exists():
            return

        self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        contract = candidates[0]

        self.entry_symbol = contract.Symbol
        self.expiration_date = selected_expiry
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiration {} strike {:.2f}".format(
                self.entry_symbol,
                selected_expiry,
                contract.Strike
            )
        )

    def _evaluate_exits(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if not self.Portfolio[self.entry_symbol].Invested:
            return

        if self._exit_order_open():
            return

        quote = self._get_current_option_quote(slice, self.entry_symbol)
        if quote is not None:
            bid, ask = quote
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("50% profit target")
                    return

    def _process_expiration(self, current_date):
        if self.entry_symbol is None or self.expiration_date is None:
            return

        if current_date >= self.expiration_date:
            self.no_entry_date = current_date

            if self._entry_order_open():
                self.entry_ticket.Cancel("Expiration processing began.")

            if self.Portfolio[self.entry_symbol].Invested:
                self._submit_exit("Expiration-day liquidation")

            return

        if self._is_trading_day_before_expiration(current_date):
            if (
                self.Time.time() >= datetime.time(15, 45) and
                self.Portfolio[self.entry_symbol].Invested
            ):
                self._submit_exit("Pre-expiration time stop")

    def _is_trading_day_before_expiration(self, current_date):
        candidate = current_date + timedelta(days=1)

        while candidate < self.expiration_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return candidate == self.expiration_date

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()

        ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.exit_tickets.append(ticket)
        self.Debug("Exit submitted: {}".format(reason))

    def _get_current_option_quote(self, slice: Slice, symbol):
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def _option_holding_exists(self):
        return (
            self.entry_symbol is not None and
            self.Portfolio[self.entry_symbol].Invested
        )

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status.IsOpen()
        )

    def _exit_order_open(self):
        return any(
            ticket is not None and ticket.Status.IsOpen()
            for ticket in self.exit_tickets
        )

    def _cancel_open_exit_orders(self):
        for ticket in self.exit_tickets:
            if ticket is not None and ticket.Status.IsOpen():
                ticket.Cancel("Replaced by liquidation order.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option exercise or assignment: {}".format(
                    order_event
                )
            )

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Entry filled: {} at {:.4f}".format(
                    self.entry_symbol,
                    self.entry_price
                )
            )

        for ticket in self.exit_tickets:
            if (
                ticket is not None and
                order_event.OrderId == ticket.OrderId and
                order_event.Status == OrderStatus.Filled
            ):
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        self.entry_symbol,
                        float(order_event.FillPrice)
                    )
                )
                break

    def OnAssignmentOrderEvent(self, assignment_event):
