            self._consume_minute_bar(spy_bar, slice)

    def _consume_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time
        local_date = start.date()
        minute_number = start.hour * 60 + start.minute

        # Only regular-session minute bars are used.
        if minute_number < 9 * 60 + 30 or minute_number >= 16 * 60:
            return

        bucket_number = (minute_number - (9 * 60 + 30)) // 5
        bucket_key = (local_date, bucket_number)

        if self._bucket_key != bucket_key:
            if self._bucket_key is not None:
                self._complete_bucket(slice)

            self._bucket_key = bucket_key
            self._bucket_bars = []

        self._bucket_bars.append(bar)

        # A complete five-minute bar is processed immediately after its
        # fifth minute arrives.
        if len(self._bucket_bars) == 5:
            self._complete_bucket(slice)
            self._bucket_key = None
            self._bucket_bars = []

    def _complete_bucket(self, slice: Slice):
        bars = self._bucket_bars
        if len(bars) != 5:
            return

        bars = sorted(bars, key=lambda bar: bar.Time)

        for first, second in zip(bars, bars[1:]):
            if second.Time != first.Time + timedelta(minutes=1):
                # Missing minute: discard the interval entirely.
                return

        start = bars[0].Time
        end = bars[-1].EndTime
        if start.hour * 60 + start.minute < 9 * 60 + 30:
            return

        fast = None
        slow = None
        self.closes.append(float(bars[-1].Close))

        if len(self.closes) >= self.fast_period:
            fast = sum(self.closes[-self.fast_period:]) / self.fast_period

        if len(self.closes) >= self.slow_period:
            slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        if (
            fast is not None
            and slow is not None
            and self._previous_fast is not None
            and self._previous_slow is not None
        ):
            bullish_cross = (
                self._previous_fast <= self._previous_slow
                and fast > slow
            )

            end_time = end.time()
            eligible_time = time(9, 45) <= end_time <= time(14, 30)

            if bullish_cross and eligible_time:
                self._evaluate_entry(slice, float(bars[-1].Close), end.date())

        self._previous_fast = fast
        self._previous_slow = slow

    def _evaluate_entry(self, slice: Slice, spy_price: float, algorithm_date):
        if self._blocked_entry_date == algorithm_date:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._is_open(self._entry_ticket):
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call at the selected expiration "
                "with a strike at least 1% OTM."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute SPY crossover"
        )

    def _check_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            candidate = chain.Contracts.get(self._held_symbol)
            if candidate is not None:
                contract = candidate
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _manage_expiration(self):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        expiry = self._held_symbol.ID.Date.date()
        today = self.Time.date()

        # Expiration processing starts on the expiration date.
        if today >= expiry:
            self._blocked_entry_date = today
            self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason: str):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(
                self._held_symbol,
                reason
            )
        )

    def _is_open(self, ticket):
        return ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        }

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self._entry_price
                    )
                )

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self._held_symbol = None
                self._entry_price = None
                self._exit_ticket = None

        if order_event.Status in {
            OrderStatus.Canceled,
            OrderStatus.Invalid
        }:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._entry_ticket = None
                self.Debug("Entry order did not fill: {}".format(order_event.Message))

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug(
            "Unexpected option exercise or assignment: {}".format(
                assignment_event
            )
        )
