            self._enter_from_chain(slice)
        elif self.pending_signal:
            self.pending_signal = False

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        end_clock = end_time.time()

        if end_clock < time(9, 30) or end_clock > time(16, 0):
            return

        averages_ready = self.fast.IsReady and self.slow.IsReady

        previous_fast = self.fast.Current.Value if averages_ready else None
        previous_slow = self.slow.Current.Value if averages_ready else None

        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        if (
            averages_ready
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and time(9, 45) <= end_clock <= time(14, 30)
        ):
            self.pending_signal = True

    def _get_chain(self, slice: Slice):
        try:
            return slice.OptionChains.get(self.option_symbol)
        except Exception:
            return None

