                contract.Right == OptionRight.Call
                and contract.Expiry.date() == selected_expiry
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike satisfies the "
                "1% out-of-the-money rule."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiry {} strike {:.2f}.".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _current_midpoint(self, slice: Slice):
        if self.held_symbol is None:
            return None

        chain = self._get_chain(slice)

        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_symbol:
                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

                return None

        return None

    def _check_profit_target(self, slice: Slice):
        if self.entry_price is None or self.exit_ticket is not None:
            return

        midpoint = self._current_midpoint(slice)

        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
