                    f"Expiration liquidation: {self.held_symbol} on {self.Time}"
                )
                self._submit_exit("expiration")

        # Evaluate minute-based exits before considering a new entry.
        self._evaluate_exits(slice)

        bar = None
        if self.spy.Symbol in slice.Bars:
            bar = slice.Bars[self.spy.Symbol]

        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        bar_date = end.date()
        bar_time = end.time()

        # Only regular-session bars are used.
        if bar_time < time(9, 30) or bar_time > time(16, 0):
            return

        session_open = datetime.combine(bar_date, time(9, 30))
        minutes_from_open = int((end - session_open).total_seconds() // 60)

        # Minute bar ending at 09:31 belongs to the five-minute bar ending 09:35.
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = session_open + timedelta(minutes=bucket_number * 5)

        # Ignore out-of-order data.
        if self.bucket_end is not None and bucket_end < self.bucket_end:
            return

        # A new bucket means the prior bucket was incomplete and is discarded.
        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        # Do not synthesize a five-minute bar if any minute is missing.
        if any(t not in self.bucket_bars for t in expected_times):
            self.bucket_end = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close

        self.bucket_end = None
        self.bucket_bars = {}

        self._on_five_minute_close(bucket_end, close, slice)

    def _on_five_minute_close(self, end: datetime, close: float, slice: Slice):
        current_time = end.time()

        # Both the preceding and current averages must be available.
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

            current_closes = list(self.closes) + [close]
            current_fast = sum(current_closes[-5:]) / 5.0
            current_slow = sum(current_closes[-20:]) / 20.0

            bullish_crossover = (
                previous_fast <= previous_slow
                and current_fast > current_slow
            )

            eligible_time = (
                time(9, 45) <= current_time <= time(14, 30)
            )

            if bullish_crossover and eligible_time:
                self._try_enter(slice, close)

        self.closes.append(close)

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None:
            return

