                        .Exchange
                        .Hours
                        .GetPreviousTradingDay(self.expiration_date)
                    )
                except Exception:
                    candidate = self.expiration_date - timedelta(days=1)
                    while candidate.weekday() >= 5:
                        candidate -= timedelta(days=1)
                    self.time_stop_date = candidate

                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price:.4f}"
                )

                if order_event.Status == OrderStatus.Filled:
                    self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"Entry order failed: {order_event.Message}")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if self.held_symbol is not None:
                    self.Debug(
                        f"Exit filled: {self.held_symbol}, "
                        f"price={order_event.FillPrice:.4f}"
                    )

                if (
                    self.held_symbol is None
                    or self.Portfolio[self.held_symbol].Quantity == 0
                ):
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None
                    self.time_stop_date = None
                    self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"Exit order failed: {order_event.Message}")
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"Unexpected option exercise or assignment: "
            f"{assignment_event}"
        )

    def _get_current_option_chain(self, slice: Slice):
        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.option.Symbol:
                return chain
        return None

    def _get_current_option_quote(self, slice: Slice, symbol: Symbol):
        if symbol in slice.QuoteBars:
            quote_bar = slice.QuoteBars[symbol]

            if quote_bar.Bid is not None and quote_bar.Ask is not None:
                return quote_bar.Bid.Close, quote_bar.Ask.Close

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == symbol:
                    return contract.BidPrice, contract.AskPrice

        return None

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )
