        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(self._option_filter)

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration = None
        self.previous_trading_day = None
        self.expiration_processed_date = None
        self.no_entry_date = None

    @staticmethod
    def _option_filter(universe):
        return (
            universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

    def OnData(self, slice):
        self._process_expiration()
        self._check_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        bucket = minute_bar.Time.replace(
            minute=(minute_bar.Time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket

        if bucket != self.bucket_start:
            self._finalize_bucket(slice)
            self.bucket_start = bucket
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

    def _finalize_bucket(self, slice):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        times = [bar.Time for bar in self.bucket_bars]
        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if times != expected:
            self.bucket_bars = []
            return

        first = self.bucket_bars[0]
        last = self.bucket_bars[-1]

        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            first.Open,
            max(bar.High for bar in self.bucket_bars),
            min(bar.Low for bar in self.bucket_bars),
            last.Close,
            sum(bar.Volume for bar in self.bucket_bars)
        )

        self.bucket_bars = []
        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar, slice):
        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.End, bar.Close)
        self.slow.Update(bar.End, bar.Close)

        if not (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
        ):
            return

        bar_time = bar.End.time()

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        bullish_crossover = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_crossover:
            self._try_entry(slice, bar.Close)

    def _try_entry(self, slice, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - today).days >= 7
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        if (
            contract.BidPrice > 0
            and contract.AskPrice > 0
            and (contract.BidPrice + contract.AskPrice) / 2
            >= 1.5 * self.entry_price
        ):
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_symbol is None or self.expiration is None:
            return

        today = self.Time.date()

        if self.expiration_processed_date == today:
            return

        if today >= self.expiration:
            self.expiration_processed_date = today
            self.no_entry_date = today
            self._submit_exit("Expiration processing")
            return

        if (
            today == self.previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.expiration_processed_date = today
            self._submit_exit("Pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(self.held_symbol, reason)
        )

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration = self.held_symbol.ID.Date.date()

                self.previous_trading_day = (
                    self.Securities[self.spy]
                    .Exchange
                    .Hours
                    .GetPreviousTradingDay(self.expiration)
