        ):
            self.Debug(
                "Exit filled: {} ({})".format(
                    self.held_symbol,
                    self.exit_ticket.Tag
                )
            )

            self.held_symbol = None
            self.entry_price = None
            self.expiration = None
            self.previous_trading_day = None
            self.exit_ticket = None

        if order_event.OrderType in (
