        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_processing_date = current_date
                self.Debug(
                    f"{self.Time}: expiration processing for {self.held_symbol}; "
                    "liquidating position"
                )
                self.SubmitExit("expiration")
                return

        # Evaluate minute-based exits.
        if self.held_symbol is not None and self.entry_price is not None:
            if self._is_expiration_stop_time(current_date):
                self.SubmitExit("expiration-eve time stop")
            else:
                quote = self._get_current_option_quote(slice, self.held_symbol)
                if quote is not None:
                    bid, ask = quote
                    if bid > 0 and ask > 0:
                        midpoint = (bid + ask) / 2.0
                        if midpoint >= 1.50 * self.entry_price:
                            self.SubmitExit("50% profit target")

        # Process the current SPY minute bar.
        if not slice.Bars.ContainsKey(self.spy):
            return

        spy_bar = slice.Bars[self.spy]
        self.last_spy_price = float(spy_bar.Close)

        completed_bar = self._add_minute_bar(spy_bar)
        if completed_bar is None:
            return

        bar_end, bar_close = completed_bar
        self._process_five_minute_close(bar_end, bar_close, slice)

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        local_time = end_time.time()

        # Regular-session minute bars only.
        if local_time <= time(9, 30) or local_time > time(16, 0):
            return None

        minute = end_time.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_hour = end_time.hour + bucket_end_minute // 60
        bucket_end_minute %= 60

        bucket_end = end_time.replace(
            hour=bucket_hour,
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )
        bucket_key = bucket_end

        if self.current_bucket is None:
            self.current_bucket = bucket_key

        if bucket_key != self.current_bucket:
            completed = None
            prior_bars = self.bucket_bars.get(self.current_bucket, {})

            # Require all five actual minute bars. Never synthesize missing data.
            if len(prior_bars) == 5:
                ordered = sorted(prior_bars.values(), key=lambda x: x.EndTime)
                completed = (
                    self.current_bucket,
                    float(ordered[-1].Close)
                )

            self.bucket_bars.pop(self.current_bucket, None)
            self.current_bucket = bucket_key
            self.bucket_bars[bucket_key] = {}

            if completed is not None:
                self.bucket_bars[bucket_key][end_time] = bar
                return completed

        self.bucket_bars.setdefault(bucket_key, {})[end_time] = bar
        return None

