        if len(self.closes) < 21:
            return

        previous_window = self.closes[-21:-1]
        current_window = self.closes[-20:]

        previous_fast = sum(previous_window[-5:]) / 5.0
        previous_slow = sum(previous_window) / 20.0
        current_fast = sum(current_window[-5:]) / 5.0
        current_slow = sum(current_window) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if not bullish_cross or not eligible_time:
            return

        if self.expiration_processing_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._is_order_open(self.entry_ticket):
            return

        self.TryEnterCall(slice)

    def TryEnterCall(self, slice):
        if self.last_spy_price is None or self.last_spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; SPY price unavailable")
            return

        chain = None
        if slice.OptionChains.ContainsKey(self.option_symbol):
            chain = slice.OptionChains[self.option_symbol]

        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; option chain unavailable")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * self.last_spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call at "
                f"{selected_expiry}"
            )
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug(
            f"{self.Time}: submitted market entry for {selected.Symbol}; "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            self.exit_ticket.Cancel(f"Replaced by {reason}")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=f"Option liquidation: {reason}"
        )

        self.Debug(
            f"{self.Time}: submitted market exit for {self.held_symbol}; "
            f"reason={reason}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"{self.Time}: unexpected option assignment/exercise event: "
                f"{order_event}"
            )

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.FillQuantity > 0:
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_price = float(order_event.FillPrice)

                    self.Debug(
                        f"{self.Time}: call entry filled; symbol={self.held_symbol}, "
                        f"price={self.entry_price}"
                    )

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(
                            f"{self.Time}: option exit filled; "
                            f"symbol={self.exit_ticket.Symbol}"
                        )
                        self.held_symbol = None
                        self.entry_price = None

                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"{self.Time}: unexpected option exercise or assignment: "
            f"{assignment_event}"
        )

    def _get_current_option_quote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _is_expiration_stop_time(self, current_date):
        if self.held_symbol is None:
            return False

        expiry_date = self.held_symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiry_date)

        return (
            current_date == prior_trading_day
            and self.Time.time() >= time(15, 45)
        )

    def _previous_trading_day(self, expiry_date):
        try:
            start = expiry_date - timedelta(days=14)
            trading_days = self.TradingCalendar.GetTradingDays(start, expiry_date)

            dates = []
            for trading_day in trading_days:
                candidate = getattr(trading_day, "Date", trading_day)
                if hasattr(candidate, "date"):
                    candidate = candidate.date()
                if candidate < expiry_date:
                    dates.append(candidate)

            if dates:
                return max(dates)
        except Exception:
            pass

        # Conservative fallback for ordinary weekday expirations.
        candidate = expiry_date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def _is_order_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )
