class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.minute_buffer = []
        self.bucket_end = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()
        held = self._held_symbol()

        if held is not None:
            expiry = held.ID.Date.date()

            if today >= expiry:
                self.blocked_entry_date = today
                self._submit_exit(held, "expiration safeguard")

            elif (
                today == expiry - timedelta(days=1)
                and self.Time.hour == 15
                and self.Time.minute == 45
            ):
                self._submit_exit(held, "pre-expiration time stop")

            self._check_profit_target(slice, held)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime.replace(tzinfo=None)
        minute = end.hour * 60 + end.minute

        session_start = 9 * 60 + 31
        session_end = 16 * 60

        if minute < session_start or minute > session_end:
            return

        first_bucket_end = 9 * 60 + 35
        bucket_end_minutes = (
            first_bucket_end
            + ((minute - first_bucket_end + 4) // 5) * 5
        )

        bucket_end = end.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60,
            second=0,
            microsecond=0,
        )

        if self.bucket_end != bucket_end:
            self.minute_buffer = []
            self.bucket_end = bucket_end

        if self.minute_buffer:
            previous_end = self.minute_buffer[-1].EndTime.replace(tzinfo=None)
            if end - previous_end != timedelta(minutes=1):
                self.minute_buffer = []

        self.minute_buffer.append(bar)

        if end != bucket_end:
            return

        if len(self.minute_buffer) != 5:
            self.minute_buffer = []
            return

        bars = self.minute_buffer
        self.minute_buffer = []

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5),
        )

        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is None
            or previous_slow is None
            or not self.fast.IsReady
            or not self.slow.IsReady
        ):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end = bar.EndTime.replace(tzinfo=None)
        eligible_time = (
            (end.hour == 9 and end.minute >= 45)
            or 10 <= end.hour <= 13
            or (end.hour == 14 and end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._try_entry(slice, bar.Close)

    def _try_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self._held_symbol() is not None:
            return

        if (
            self.entry_ticket is not None
            and self.entry_ticket.Status
            in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped selection: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)

        calls = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in calls
        )

        candidates = [
            contract
            for contract in calls
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol),
            ),
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            False,
            "bullish five-minute crossover",
        )

        self.Debug(
            "Entry submitted: {} exp {} strike {}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike,
            )
        )

    def _check_profit_target(self, slice: Slice, held: Symbol):
        if self.entry_price is None or self._exit_is_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = chain.Contracts.get(held)
        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit(held, "50% profit target")

    def _submit_exit(self, symbol: Symbol, reason: str):
        if self._exit_is_open():
            return

        quantity = -self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            symbol,
            quantity,
            False,
            reason,
        )

        self.Debug(
            "Exit submitted: {} ({})".format(symbol, reason)
        )

    def _exit_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status
            in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        )

    def _held_symbol(self):
        if (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Invested
        ):
            return self.entry_symbol

        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.entry_symbol,
                        self.entry_price,
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.Debug(
                    "Entry order did not fill: {}".format(
                        order_event.Status
                    )
                )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.entry_symbol))
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected option assignment: {}".format(
                assignment_event
            )
        )

    def OnExerciseOrderEvent(self, exercise_event: OrderEvent):
        self.Debug(
            "Unexpected option exercise: {}".format(
                exercise_event
            )
        )

