        current_time = self.Time.time()

        self._process_expiration_safety(current_date)
        self._evaluate_profit_target(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        if (
            self.entry_symbol is None
            and self.entry_order_id is None
            and self.expiration_block_date != current_date
        ):
            self._evaluate_entry(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        session_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            9,
            30
        )

        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_offset = (minutes_from_open // 5) * 5
        bucket_start = session_start + timedelta(minutes=bucket_offset)

        if self.bucket_start != bucket_start:
            if self.bucket_start is not None:
                self._finish_five_minute_bar(slice)

            self.bucket_start = bucket_start
            self.bucket_last_minute = bar_time
            self.bucket_count = 1
            self.bucket_valid = True
            self.bucket_close = bar.Close
            return

        expected_minute = self.bucket_last_minute + timedelta(minutes=1)

        if bar_time != expected_minute:
            self.bucket_valid = False

        self.bucket_last_minute = bar_time
        self.bucket_count += 1
        self.bucket_close = bar.Close

    def _finish_five_minute_bar(self, slice: Slice):
        if self.bucket_start is None:
            return

        completed = (
            self.bucket_count == 5
            and self.bucket_valid
            and self.bucket_close is not None
        )

        if completed:
            bar_end = self.bucket_start + timedelta(minutes=5)
            close = float(self.bucket_close)

            self.closes.append(close)

            current_fast = None
            current_slow = None

            if len(self.closes) >= 5:
                current_fast = sum(list(self.closes)[-5:]) / 5.0

            if len(self.closes) >= 20:
                current_slow = sum(self.closes) / 20.0

            bullish_cross = (
                self.previous_fast is not None
                and self.previous_slow is not None
                and current_fast is not None
                and current_slow is not None
                and self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )

            if current_fast is not None and current_slow is not None:
                if (
                    bullish_cross
                    and time(9, 45) <= bar_end.time() <= time(14, 30)
                ):
