        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end = bar.EndTime
        start = end - timedelta(minutes=5)

        # Only use regular-session bars aligned to New York clock boundaries.
        if start.time() < time(9, 30) or end.time() > time(16, 0):
            return

        if end.minute % 5 != 0 or end.second != 0:
            return

        if self._has_option_holding() or self._entry_is_open():
            return

        self.fast_window.append(float(bar.Close))
        self.slow_window.append(float(bar.Close))

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_window) / len(self.fast_window)
        slow = sum(self.slow_window) / len(self.slow_window)

        crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        if crossover and time(9, 45) <= end.time() <= time(14, 30):
            self.pending_signal = (end, float(bar.Close))

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option through expiration processing.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self.time_stop_date = None

                if self._has_option_holding():
                    self._submit_exit("expiration processing")
                elif self._entry_is_open():
                    self.entry_ticket.Cancel("Expiration processing")
                return

