        strike_floor = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() == selected_expiry and
            float(contract.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol}, "
            f"strike={selected.Strike}, expiry={selected.Expiry.date()}"
        )

    def _submit_exit(self, reason):
        if self.held_symbol is None or not self._has_option_holding():
            return

        if self._exit_is_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug(f"Call exit submitted: {reason}")

    def _find_current_contract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(date_value.year, date_value.month, date_value.day)
        ):
            date_value -= timedelta(days=1)

        return date_value

    def _has_option_holding(self):
        return (
            self.held_symbol is not None and
            self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in {
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            }
        )

    def _exit_is_open(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status in {
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            }
        )

    def _cancel_open_exit(self):
        if self._exit_is_open():
            self.exit_ticket.Cancel("Profit target reached")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                if order_event.FillQuantity > 0:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)

                    expiry_date = self.held_symbol.ID.Date.date()
                    self.time_stop_date = self._previous_trading_day(
                        expiry_date
                    )

                    self.Debug(
                        f"Call entry filled: {self.held_symbol}, "
                        f"price={self.entry_price:.4f}"
                    )

            elif order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Call exit filled: {order_event.Symbol}, "
                    f"price={float(order_event.FillPrice):.4f}"
                )

                if (
                    self.held_symbol is None or
                    self.Portfolio[self.held_symbol].Quantity <= 0
                ):
                    self.held_symbol = None
                    self.entry_price = None
                    self.time_stop_date = None
                    self.exit_ticket = None

        order_type = getattr(order_event, "OrderType", None)
        is_assignment = getattr(order_event, "IsAssignment", False)

        if is_assignment or order_type == OrderType.OptionExercise:
            self.Debug(
