                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.minute_bucket_start = None
        self.minute_bucket = {}

        self.pending_signal = False
        self.pending_signal_price = None

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._process_option_exit(slice)
        self._process_spy_minute(slice)

        if self.pending_signal:
            signal_price = self.pending_signal_price
            self.pending_signal = False
            self.pending_signal_price = None

            if self._entry_is_blocked(current_date):
                return

            self._attempt_entry(slice, signal_price)

    def _process_spy_minute(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy.Symbol):
            return

        bar = slice.Bars[self.spy.Symbol]
        bar_time = bar.Time
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_clock < time(9, 30) or bar_clock >= time(16, 0):
            return

        session_start = bar_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )

        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.minute_bucket_start is None:
            self.minute_bucket_start = bucket_start

        if bucket_start.date() != self.minute_bucket_start.date():
            self.minute_bucket_start = bucket_start
            self.minute_bucket = {}

        if bucket_start != self.minute_bucket_start:
            self._finish_five_minute_bar()
            self.minute_bucket_start = bucket_start
            self.minute_bucket = {}

        self.minute_bucket[bar_time] = bar.Close

    def _finish_five_minute_bar(self):
        if self.minute_bucket_start is None:
            return

        expected_times = {
            self.minute_bucket_start + timedelta(minutes=i)
            for i in range(5)
        }

        # Missing minute data invalidates this five-minute interval.
        if set(self.minute_bucket.keys()) != expected_times:
            return

        close = self.minute_bucket[
            self.minute_bucket_start + timedelta(minutes=4)
        ]

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        crossover_time = self.minute_bucket_start + timedelta(minutes=5)
        crossover_clock = crossover_time.time()

        eligible_time = (
            crossover_clock >= time(9, 45)
            and crossover_clock <= time(14, 30)
        )

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self.pending_signal = True
            self.pending_signal_price = close

    def _attempt_entry(self, slice: Slice, spy_price: float):
        if self.entry_ticket is not None:
            if self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        contracts = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        contracts.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = contracts[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            f"Entry submitted: {self.entry_symbol}; "
            f"expiration={selected_expiration}; strike={selected.Strike}"
        )

    def _process_option_exit(self, slice: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        quote = slice.QuoteBars.get(self.entry_symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

