from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option_security.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.previous_five_minute_end = None
        self.pending_signal = False
        self.pending_signal_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_blocked_date = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_end = bar.EndTime
        bar_end_time = bar_end.time()

        # Accept only regular-session bars aligned to New York five-minute boundaries.
        if not (time(9, 35) <= bar_end_time <= time(16, 0)):
            return

        if bar_end_time.minute % 5 != 0:
            return

        # Do not bridge a missing five-minute interval.
        if self.previous_five_minute_end is not None:
            if bar_end - self.previous_five_minute_end != timedelta(minutes=5):
                self.previous_five_minute_end = bar_end
                return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)
        self.previous_five_minute_end = bar_end

        if (
            previous_fast is None
            or previous_slow is None
            or not self.fast.IsReady
            or not self.slow.IsReady
        ):
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if time(9, 45) <= bar_end_time <= time(14, 30):
            if bullish_crossover:
                self.pending_signal = True
                self.pending_signal_date = self.Time.date()

    def OnData(self, slice):
        current_date = self.Time.date()

        self.ProcessExpirationProtection(slice, current_date)
        self.ProcessProfitTarget(slice)

        if not self.pending_signal:
            return

        # The signal is evaluated only once, in the Slice immediately following
        # the eligible completed five-minute bar.
        self.pending_signal = False

        if self.pending_signal_date != current_date:
            return

        if self.expiration_blocked_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.IsEntryOrderOpen():
            return

        self.TryEnterFromCurrentChain(slice, current_date)

    def TryEnterFromCurrentChain(self, slice, current_date):
        option_chain = slice.OptionChains.get(self.option_symbol)
        spy_bar = slice.Bars.get(self.spy)

        if option_chain is None or spy_bar is None:
            self.Debug("Skipped call selection: option chain or SPY price unavailable.")
            return

        spy_price = float(spy_bar.Close)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry_date = current_date + timedelta(days=7)

        contracts = list(option_chain.Contracts.Values)
        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry_date
            }
        )

        if not eligible_expiries:
            self.Debug("Skipped call selection: no expiration at least seven days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        eligible_contracts = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible_contracts:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected_contract = sorted(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected_contract.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.held_option,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Call entry submitted: {self.held_option}, "
            f"expiry={selected_expiry}, strike={selected_contract.Strike}"
        )

    def ProcessProfitTarget(self, slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0 or self.entry_price is None:
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrders()
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -holding.Quantity,
                tag="50 percent profit target"
            )
            self.Debug(
                f"Profit-target exit submitted: {self.held_option}, "
                f"midpoint={midpoint:.4f}"
            )

    def ProcessExpirationProtection(self, slice, current_date):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_blocked_date = current_date

            if self.IsEntryOrderOpen():
                self.entry_ticket.Cancel("Expiration protection")
                self.entry_ticket = None

            holding = self.Portfolio[self.held_option]
            if holding.Quantity > 0 and not self.IsExitOrderOpen():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity,
                    tag="Expiration protection"
                )
                self.Debug(
                    f"Expiration-protection exit submitted: {self.held_option}"
                )
            return

        if self.Time.time() != time(15, 45):
            return

        if self.IsTradingDayImmediatelyBefore(current_date, expiry_date):
            holding = self.Portfolio[self.held_option]
            if holding.Quantity > 0 and not self.IsExitOrderOpen():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity,
                    tag="Pre-expiration time stop"
                )
                self.Debug(
                    f"Pre-expiration exit submitted: {self.held_option}"
                )

    def IsTradingDayImmediatelyBefore(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while next_date < expiry_date:
            test_datetime = datetime(
                next_date.year, next_date.month, next_date.day
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(test_datetime):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def CancelOpenExitOrders(self):
        if self.exit_ticket is not None and self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replaced by liquidation order")
            self.exit_ticket = None

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Call entry filled: {order_event.Symbol}, "
                        f"price={self.entry_price:.4f}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_,
                ):
                    self.entry_ticket = None
                    self.held_option = None
                    self.entry_price = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Call exit filled: {order_event.Symbol}")
                    self.exit_ticket = None
                    self.entry_ticket = None
                    self.held_option = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_order_event):
        self.Debug(
            f"Unexpected option exercise or assignment received: "
            f"{assignment_order_event}"
        )
