                self.pending_signal_date = self.Time.date()

    def OnData(self, slice):
        current_date = self.Time.date()

        self.ProcessExpirationProtection(slice, current_date)
        self.ProcessProfitTarget(slice)

        if not self.pending_signal:
            return

        # The signal is evaluated only once, in the Slice immediately following
        # the eligible completed five-minute bar.
        self.pending_signal = False

        if self.pending_signal_date != current_date:
            return

        if self.expiration_blocked_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.IsEntryOrderOpen():
            return

        self.TryEnterFromCurrentChain(slice, current_date)

    def TryEnterFromCurrentChain(self, slice, current_date):
        option_chain = slice.OptionChains.get(self.option_symbol)
        spy_bar = slice.Bars.get(self.spy)

        if option_chain is None or spy_bar is None:
            self.Debug("Skipped call selection: option chain or SPY price unavailable.")
            return

        spy_price = float(spy_bar.Close)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry_date = current_date + timedelta(days=7)

        contracts = list(option_chain.Contracts.Values)
        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry_date
            }
        )

        if not eligible_expiries:
            self.Debug("Skipped call selection: no expiration at least seven days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        eligible_contracts = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible_contracts:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected_contract = sorted(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected_contract.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.held_option,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Call entry submitted: {self.held_option}, "
            f"expiry={selected_expiry}, strike={selected_contract.Strike}"
        )

    def ProcessProfitTarget(self, slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0 or self.entry_price is None:
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrders()
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -holding.Quantity,
                tag="50 percent profit target"
            )
