            self.expiration_blocked_date = current_date

            if self.IsEntryOrderOpen():
                self.entry_ticket.Cancel("Expiration protection")
                self.entry_ticket = None

            holding = self.Portfolio[self.held_option]
            if holding.Quantity > 0 and not self.IsExitOrderOpen():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity,
                    tag="Expiration protection"
                )
                self.Debug(
                    f"Expiration-protection exit submitted: {self.held_option}"
                )
            return

        if self.Time.time() != time(15, 45):
            return

        if self.IsTradingDayImmediatelyBefore(current_date, expiry_date):
            holding = self.Portfolio[self.held_option]
            if holding.Quantity > 0 and not self.IsExitOrderOpen():
                self.CancelOpenExitOrders()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -holding.Quantity,
                    tag="Pre-expiration time stop"
                )
                self.Debug(
                    f"Pre-expiration exit submitted: {self.held_option}"
                )

    def IsTradingDayImmediatelyBefore(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while next_date < expiry_date:
            test_datetime = datetime(
                next_date.year, next_date.month, next_date.day
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(test_datetime):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def CancelOpenExitOrders(self):
        if self.exit_ticket is not None and self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replaced by liquidation order")
            self.exit_ticket = None

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
