from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_date = None
        self._bucket_end = None
        self._minute_bars = []

        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry_signal = False

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self._held_symbol is not None:
            expiration = self._held_symbol.ID.Date.date()

            if today >= expiration:
                self._expiration_block_date = today
                self._submit_exit("expiration processing")

            elif (
                today == self._preceding_trading_day(expiration)
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("pre-expiration time stop")

        if self.spy.Symbol in slice.Bars:
            self._accept_minute_bar(slice.Bars[self.spy.Symbol])

        if self._pending_entry_signal:
            self._pending_entry_signal = False
            self._try_entry(slice)

        if self._held_symbol is not None and self._entry_price is not None:
            self._check_profit_target(slice)

    def _accept_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime.replace(tzinfo=None)
        bar_date = local_end.date()
        end_minute = local_end.hour * 60 + local_end.minute

        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if bar_date != self.Time.date():
            return

        if end_minute <= session_start or end_minute > session_end:
            return

        bucket_end_minute = (
            session_start
            + ((end_minute - session_start + 4) // 5) * 5
        )

        if self._bucket_end is None:
            self._bucket_date = bar_date
            self._bucket_end = bucket_end_minute
        elif (
            bar_date != self._bucket_date
            or bucket_end_minute != self._bucket_end
        ):
            self._finalize_bucket()

            self._bucket_date = bar_date
            self._bucket_end = bucket_end_minute

        self._minute_bars.append(bar)

    def _finalize_bucket(self):
        if not self._minute_bars:
            return

        expected = [
            self._bucket_end - 4,
            self._bucket_end - 3,
            self._bucket_end - 2,
            self._bucket_end - 1,
            self._bucket_end,
        ]

        actual = []
        for bar in self._minute_bars:
            local_end = bar.EndTime.replace(tzinfo=None)
            actual.append(local_end.hour * 60 + local_end.minute)

        if len(actual) == 5 and actual == expected:
            close = self._minute_bars[-1].Close
            bar_end = self._minute_bars[-1].EndTime

            if self.fast.IsReady and self.slow.IsReady:
                self._previous_fast = self.fast.Current.Value
                self._previous_slow = self.slow.Current.Value

            self.fast.Update(IndicatorDataPoint(bar_end, close))
            self.slow.Update(IndicatorDataPoint(bar_end, close))

            if (
                self.fast.IsReady
                and self.slow.IsReady
                and self._previous_fast is not None
                and self._previous_slow is not None
            ):
                current_end = bar_end.replace(tzinfo=None)

                eligible_time = (
                    current_end.hour * 60 + current_end.minute
                )

                bullish_cross = (
                    self._previous_fast <= self._previous_slow
                    and self.fast.Current.Value > self.slow.Current.Value
                )

                if (
                    bullish_cross
                    and 9 * 60 + 45 <= eligible_time <= 14 * 60 + 30
                ):
                    self._pending_entry_signal = True

        self._minute_bars = []

    def _try_entry(self, slice: Slice):
        if self._expiration_block_date == self.Time.date():
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and not self._ticket_finished(
            self._entry_ticket
        ):
            return

        chain = self._get_option_chain(slice)

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiration = expirations[0]
        underlying_price = float(self.Securities[self.spy.Symbol].Price)
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

    def _check_profit_target(self, slice: Slice):
        if self._exit_ticket is not None and not self._ticket_finished(
            self._exit_ticket
        ):
            return

        contract = None

        for chain in self._all_option_chains(slice):
            for candidate in chain:
                if candidate.Symbol == self._held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        if self._exit_ticket is not None and not self._ticket_finished(
            self._exit_ticket
        ):
            return

        if self._entry_ticket is not None and not self._ticket_finished(
            self._entry_ticket
        ):
            return

        quantity = self.Portfolio[self._held_symbol].Quantity

        if quantity == 0:
            return

        if self._exit_ticket is not None:
            self._exit_ticket.Cancel("Replacing exit order.")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(getattr(order_event, "Message", "")).lower()

        if (
            getattr(order_event, "IsAssignment", False)
            or "assignment" in message
            or "exercise" in message
        ):
            self.Debug(
                "Unexpected option exercise or assignment: "
                + str(order_event)
            )

        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self._held_symbol = order_event.Symbol
                    self._entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entered 1 call "
                        + str(self._held_symbol)
                        + " at "
                        + str(self._entry_price)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None
                ):
                    self._entry_ticket = None

        if self._exit_ticket is not None:
            if order_event.OrderId == self._exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited call "
                        + str(order_event.Symbol)
                        + " at "
                        + str(order_event.FillPrice)
                    )
                    self._exit_ticket = None
                    self._held_symbol = None
                    self._entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None
                ):
                    self._exit_ticket = None

    def _get_option_chain(self, slice: Slice):
        for chain in self._all_option_chains(slice):
            return chain
        return None

    def _all_option_chains(self, slice: Slice):
        for _, chain in slice.OptionChains:
            yield chain

    def _ticket_finished(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        )

    def _preceding_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
