from AlgorithmImports import *
from collections import defaultdict
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.minute_groups = {}
        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.exit_reason = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Never intentionally hold through expiration.
        self._process_expiration_safety(current_date)

        # Evaluate the profit target on every minute Slice.
        self._evaluate_profit_target(slice)

        spy_bar = None
        if self.spy.Symbol in slice.Bars:
            spy_bar = slice.Bars[self.spy.Symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.EndTime
        current_date = local_time.date()
        current_minute = local_time.hour * 60 + local_time.minute

        # Regular-session minute bars only.
        if current_minute < 9 * 60 + 31 or current_minute > 16 * 60:
            return

        # Five-minute groups: 09:31-09:35, 09:36-09:40, etc.
        offset = current_minute - (9 * 60 + 31)
        bucket_end_minute = 9 * 60 + 35 + (offset // 5) * 5
        bucket_end = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_end_minute // 60,
            bucket_end_minute % 60
        )

        group_key = (current_date, bucket_end)

        # Finalize a prior group when a new group begins.
        prior_keys = [
            key for key in self.minute_groups
            if key[0] == current_date and key[1] < bucket_end
        ]

        for prior_key in sorted(prior_keys, key=lambda key: key[1]):
            bars = self.minute_groups.pop(prior_key)
            self._finalize_group(prior_key[1], bars, slice)

        if group_key not in self.minute_groups:
            self.minute_groups[group_key] = {}

        # Do not count duplicate minute bars.
        self.minute_groups[group_key][local_time] = minute_bar

        # The current group is complete exactly when its ending minute arrives.
        if current_minute == bucket_end_minute:
            bars = self.minute_groups.pop(group_key)
            self._finalize_group(bucket_end, bars, slice)

    def _finalize_group(self, bucket_end: datetime, bars: dict, slice: Slice):
        # Missing minute data means no five-minute bar is created.
        if len(bars) != 5:
            return

        ordered = sorted(bars.values(), key=lambda bar: bar.EndTime)

        expected_minutes = {
            (bucket_end - timedelta(minutes=i)).replace(second=0, microsecond=0)
            for i in range(5)
        }
        actual_minutes = {
            bar.EndTime.replace(second=0, microsecond=0)
            for bar in ordered
        }

        if actual_minutes != expected_minutes:
            return

        close = ordered[-1].Close
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        previous_closes = self.closes[:-1]
        previous_fast = sum(previous_closes[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous_closes[-self.slow_period:]) / self.slow_period

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self._has_option_holding() or self._entry_order_open():
            return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if expiry_date < minimum_expiry:
                    continue

                if contract.Right != OptionRight.Call:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no eligible call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
