        if not (time(9, 30) <= local_start.time() < time(16, 0)):
            return

        bucket_start = local_start.replace(
            minute=(local_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        elif bucket_start != self.bucket_start:
            self._finish_bucket(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) > 5:
            self.bucket_bars = []

        if len(self.bucket_bars) == 5:
            self._finish_bucket(slice)
            self.bucket_bars = []
            self.bucket_start = None

    def _finish_bucket(self, slice):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        bars = sorted(self.bucket_bars, key=lambda x: x.Time)

        if any(
            bars[i].Time - bars[i - 1].Time != timedelta(minutes=1)
            for i in range(1, len(bars))
        ):
            self.bucket_bars = []
            return

        close = float(bars[-1].Close)

        self.fast.Update(close)
        self.slow.Update(close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        end_time = self.bucket_start + timedelta(minutes=5)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_entry(slice, close)

    def _try_entry(self, slice, spy_price):
        if self.held_symbol is not None or self._entry_order_open():
            return

        if self.no_entry_date == self.Time.date():
            return

        try:
            chain = slice.OptionChains[self.option]
        except Exception:
            self.Debug("Skipped selection: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
            self.Debug("Skipped selection: no expiration at least 7 days out")
            return

        selected_expiry = expiries[0]

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            False,
            "MA crossover call entry"
        )

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _current_midpoint(self, slice, symbol):
        try:
            quote = slice.QuoteBars[symbol]
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

        except Exception:
            pass

        return None

    def _liquidate_held(self, reason):
        if self.held_symbol is None or self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self._cancel_open_exit_order()

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            False,
            reason
        )

        self.Debug(
            "Exit submitted (" + reason + "): " + str(self.held_symbol)
        )

    def _previous_trading_date(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _cancel_open_exit_order(self):
        if self._exit_order_open():
            self.exit_ticket.Cancel("replaced by liquidation")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: "
                    + str(order_event.Symbol)
                    + " @ "
                    + str(order_event.FillPrice)
                )

                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected exercise or assignment: "
            + str(assignment_event)
        )

        self.held_symbol = None
        self.entry_price = None

