from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.aggregate_date = None
        self.aggregate_start = None
        self.aggregate_bars = []
        self.aggregate_valid = True

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_expiration_processing(current_date)
        self._evaluate_time_stop(current_date)
        self._evaluate_profit_target(slice)

        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.spy not in slice.Bars:
            return

        self._process_spy_minute_bar(slice.Bars[self.spy], slice)

    def _process_spy_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time
        local_date = start.date()
        local_time = start.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute_offset = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        interval_start_minutes = (minute_offset // 5) * 5
        interval_start = datetime.combine(
            local_date,
            time(9, 30)
        ) + timedelta(minutes=interval_start_minutes)

        if self.aggregate_start is None:
            self._begin_interval(interval_start)

        elif interval_start != self.aggregate_start:
            self._complete_interval(slice)
            self._begin_interval(interval_start)

        expected_time = self.aggregate_start + timedelta(
            minutes=len(self.aggregate_bars)
        )

        if start != expected_time:
            self.aggregate_valid = False

        if len(self.aggregate_bars) < 5:
            self.aggregate_bars.append(bar)

        if len(self.aggregate_bars) == 5:
            self._complete_interval(slice)
            self._begin_interval(self.aggregate_start + timedelta(minutes=5))

    def _begin_interval(self, interval_start):
        self.aggregate_date = interval_start.date()
        self.aggregate_start = interval_start
        self.aggregate_bars = []
        self.aggregate_valid = True

    def _complete_interval(self, slice: Slice):
        if (
            self.aggregate_start is None
            or len(self.aggregate_bars) != 5
            or not self.aggregate_valid
        ):
            return

        close = self.aggregate_bars[-1].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

        current_fast = None
        current_slow = None

        if len(self.fast_values) == 5:
            current_fast = sum(self.fast_values) / 5.0

        if len(self.slow_values) == 20:
            current_slow = sum(self.slow_values) / 20.0

        bar_end = self.aggregate_start + timedelta(minutes=5)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(slice, close)

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.entry_ticket is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.option not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option]
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.held_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        contract = None
        if self.option in slice.OptionChains:
            for candidate in slice.OptionChains[self.option]:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self, current_date):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested or self.exit_ticket is not None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        preceding_trading_day = self._preceding_trading_day(expiry_date)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration-eve time stop")

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date

            holding = self.Portfolio[self.held_symbol]
            if holding.Invested and self.exit_ticket is None:
                self._submit_exit("expiration protection liquidation")

    def _preceding_trading_day(self, expiry_date):
        date = expiry_date - timedelta(days=1)

        while date.weekday() >= 5:
            date -= timedelta(days=1)

        return date

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Replacing open exit order"
            )

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, Symbol={1}".format(
                reason,
                self.held_symbol
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment received.")

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: Symbol={0}, Price={1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
                self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Call exit filled: Symbol={0}, Price={1}".format(
                        self.held_symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None

                if (
                    self.held_symbol is None
                    or not self.Portfolio[self.held_symbol].Invested
                ):
                    self.held_symbol = None
                    self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug(
            "Unexpected option exercise or assignment handling event: {0}".format(
