        if current_minutes <= base_minutes:
            return end.replace(hour=9, minute=35)

        offset = current_minutes - base_minutes
        rounded = ((offset + 4) // 5) * 5

        return end.replace(hour=9, minute=35) + timedelta(minutes=rounded)

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _is_open(ticket):
        return (
            ticket is not None
            and ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            )
        )
