from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.options = self.AddOption("SPY", Resolution.Minute)
        self.options.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.current_bucket = None
        self.bucket_minutes = {}
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        # Prevent replacement entries on a date where expiration processing began.
        if self.held_symbol is not None:
            expiry_date = self._expiry_date(self.held_symbol)

            if expiry_date == current_date:
                if self.expiration_block_date != current_date:
                    self.expiration_block_date = current_date
                    self.Debug(
                        f"{self.Time}: expiration processing; liquidating "
                        f"{self.held_symbol}"
                    )
                    self._submit_exit("expiration-day liquidation")

            elif self._is_open_position():
                self._evaluate_profit_target(data)

                if (
                    self.Time.time() >= time(15, 45)
                    and self._previous_trading_day(expiry_date) == current_date
                ):
                    self._submit_exit("pre-expiration time stop")

        # Build five-minute bars only from complete sets of five minute bars.
        if self.spy.Symbol not in data.Bars:
            return

        minute_bar = data.Bars[self.spy.Symbol]
        local_end = minute_bar.EndTime

        if not self._regular_session_minute(local_end):
            return

        bucket_end = self._bucket_end(local_end)
        bucket_key = bucket_end

        if self.current_bucket is None:
            self.current_bucket = bucket_key

        if bucket_key != self.current_bucket:
            self._flush_bucket(self.current_bucket, data)
            self.current_bucket = bucket_key

        minute_key = local_end.replace(second=0, microsecond=0)

        # Ignore duplicate minute data.
        if minute_key in self.bucket_minutes:
            return

        self.bucket_minutes[minute_key] = minute_bar
        self.bucket_bars[bucket_key] = self.bucket_bars.get(
            bucket_key,
            {
                "open": minute_bar.Open,
                "high": minute_bar.High,
                "low": minute_bar.Low,
                "close": minute_bar.Close,
                "volume": 0
            }
        )

        aggregate = self.bucket_bars[bucket_key]
        aggregate["high"] = max(aggregate["high"], minute_bar.High)
        aggregate["low"] = min(aggregate["low"], minute_bar.Low)
        aggregate["close"] = minute_bar.Close
        aggregate["volume"] += minute_bar.Volume

    def _flush_bucket(self, bucket_end, data):
        minutes = [
            minute for minute in self.bucket_minutes
            if self._bucket_end(minute) == bucket_end
        ]

        # Missing minutes invalidate the interval. No synthetic bar is created.
        if len(minutes) != 5:
            self.bucket_minutes = {
                k: v for k, v in self.bucket_minutes.items()
                if self._bucket_end(k) != bucket_end
            }
            self.bucket_bars.pop(bucket_end, None)
            return

        aggregate = self.bucket_bars.get(bucket_end)
        if aggregate is None:
            return

        bar = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy.Symbol,
            aggregate["open"],
            aggregate["high"],
            aggregate["low"],
            aggregate["close"],
            aggregate["volume"],
            timedelta(minutes=5)
        )
        bar.EndTime = bucket_end

        self._on_five_minute_bar(bar, data)

        self.bucket_minutes = {
            k: v for k, v in self.bucket_minutes.items()
            if self._bucket_end(k) != bucket_end
        }
        self.bucket_bars.pop(bucket_end, None)

    def _on_five_minute_bar(self, bar, data):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(bar.Close))

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and eligible_time
            and self.expiration_block_date != self.Time.date()
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._select_and_enter(data, float(bar.Close))

    def _select_and_enter(self, data, spy_price):
        chains = list(data.OptionChains.Values)
        if not chains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = self._expiry_date(contract.Symbol)

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug(f"{self.Time}: skipped entry; no qualifying expiration")
            return

        nearest_expiry = min(self._expiry_date(c.Symbol) for c in contracts)

        strike_candidates = [
            c for c in contracts
            if self._expiry_date(c.Symbol) == nearest_expiry
            and c.Strike >= 1.01 * spy_price
        ]

        if not strike_candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call strike"
            )
            return

        selected = min(
            strike_candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover"
        )

        self.Debug(
            f"{self.Time}: submitted entry for {selected.Symbol}"
        )

    def _evaluate_profit_target(self, data):
        if not self._is_open_position() or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        quote = self._get_current_contract(data, self.held_symbol)
        if quote is None:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"{self.Time}: submitted exit for {self.held_symbol}; {reason}"
        )

    def _get_current_contract(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                self.Debug(
                    f"{self.Time}: entered {self.held_symbol} at "
                    f"{self.entry_price:.4f}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exited {order_event.Symbol} at "
                    f"{order_event.FillPrice:.4f}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"{self.Time}: unexpected exercise or assignment: "
            f"{assignment_event}"
        )

    def _is_open_position(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def _entry_order_open(self):
        return self._ticket_open(self.entry_ticket)

    def _exit_order_open(self):
        return self._ticket_open(self.exit_ticket)

    def _ticket_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _expiry_date(self, symbol):
        return symbol.ID.Date.date()

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = datetime.combine(
            expiry_date,
            datetime.min.time()
        ) - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _regular_session_minute(self, timestamp):
        t = timestamp.time()
        return time(9, 31) <= t <= time(16, 0)

    def _bucket_end(self, timestamp):
        minute = timestamp.minute
        end_minute = ((minute + 4) // 5) * 5

        if end_minute == 60:
            return (
                timestamp.replace(
                    minute=0,
                    second=0,
                    microsecond=0
                ) + timedelta(hours=1)
            )

        return timestamp.replace(
            minute=end_minute,
            second=0,
            microsecond=0
        )
