        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"{self.Time}: submitted exit for {self.held_symbol}; {reason}"
        )

    def _get_current_contract(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None

                self.Debug(
                    f"{self.Time}: entered {self.held_symbol} at "
                    f"{self.entry_price:.4f}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exited {order_event.Symbol} at "
                    f"{order_event.FillPrice:.4f}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"{self.Time}: unexpected exercise or assignment: "
            f"{assignment_event}"
        )

    def _is_open_position(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def _entry_order_open(self):
        return self._ticket_open(self.entry_ticket)

    def _exit_order_open(self):
        return self._ticket_open(self.exit_ticket)

    def _ticket_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _expiry_date(self, symbol):
        return symbol.ID.Date.date()

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = datetime.combine(
            expiry_date,
            datetime.min.time()
        ) - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _regular_session_minute(self, timestamp):
        t = timestamp.time()
        return time(9, 31) <= t <= time(16, 0)

    def _bucket_end(self, timestamp):
