        end_minute = ((minute + 4) // 5) * 5

        if end_minute == 60:
            return (
                timestamp.replace(
                    minute=0,
                    second=0,
                    microsecond=0
                ) + timedelta(hours=1)
            )

        return timestamp.replace(
            minute=end_minute,
            second=0,
