        if completed is None:
            return

        close_price, bar_end = completed
        self.fast.Update(bar_end, close_price)
        self.slow.Update(bar_end, close_price)

        if not self.fast.IsReady or not self.slow.IsReady:
            self._previous_fast = self.fast.Current.Value
            self._previous_slow = self.slow.Current.Value
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        if not bullish_cross:
            return

        end_time = bar_end.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
