            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(minute in self._bucket_bars for minute in expected_minutes):
            return None

        if local_start != expected_minutes[-1]:
            return None

        bars = [self._bucket_bars[m] for m in expected_minutes]
        close_price = bars[-1].Close

        self._bucket_bars = {}
        self._bucket_start = None

