        if self._held_symbol is None or self._exit_order_open():
            return

        expiry = self._held_symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_liquidation("expiration time stop")

    def _process_expiration_safety(self):
        if self._held_symbol is None:
