from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-100, 100)
                       .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None

        self._bucket_date = None
        self._bucket_start = None
        self._bucket_bars = []

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_guard_date = None
        self._no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration_guard(current_date)

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop()

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar, slice: Slice):
        local_time = minute_bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start <= local_time.time() < session_end):
            return

        bar_date = local_time.date()

        if self._bucket_date != bar_date:
            self._flush_bucket(slice)
            self._bucket_date = bar_date
            self._bucket_start = None
            self._bucket_bars = []

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
            - (9 * 60 + 30)
        )
        bucket_minute = (minutes_from_open // 5) * 5
        bucket_start = datetime.combine(
            bar_date, session_start
        ) + timedelta(minutes=bucket_minute)

        if self._bucket_start is None:
            self._bucket_start = bucket_start

        if bucket_start != self._bucket_start:
            self._flush_bucket(slice)
            self._bucket_start = bucket_start
            self._bucket_bars = []

        self._bucket_bars.append(minute_bar)

    def _flush_bucket(self, slice: Slice):
        if not self._bucket_bars or self._bucket_start is None:
            return

        bars = sorted(self._bucket_bars, key=lambda b: b.EndTime)

        expected_times = [
            self._bucket_start + timedelta(minutes=i + 1)
            for i in range(5)
        ]

        actual_times = []
        for bar in bars:
            end_time = bar.EndTime
            if end_time.tzinfo is not None:
                end_time = end_time.replace(tzinfo=None)
            actual_times.append(end_time)

        if len(actual_times) != 5 or actual_times != expected_times:
            self._bucket_bars = []
            return

        close = float(bars[-1].Close)
        bar_end = self._bucket_start + timedelta(minutes=5)

        self._update_averages_and_test_signal(bar_end, close, slice)
        self._bucket_bars = []

    def _update_averages_and_test_signal(self, bar_end: datetime,
                                         close: float, slice: Slice):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        point = IndicatorDataPoint(self.spy_symbol, bar_end, close)
        self.fast.Update(point)
        self.slow.Update(point)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self._previous_fast = self.fast.Current.Value
        self._previous_slow = self.slow.Current.Value

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self._no_entry_date == self.Time.date():
            return

        if self._entry_ticket is not None and not self._entry_ticket.Status.IsClosed():
            return

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        self._select_and_enter(slice, float(spy_bar.Close))

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expiries = sorted({
            self._date_of(contract.Expiry)
            for contract in contracts
            if self._date_of(contract.Expiry) >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if self._date_of(contract.Expiry) == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self._entry_price:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit()
        self._exit_ticket = self.MarketOrder(
            self._held_symbol, -quantity
        )
        self.Debug(
            "Exit submitted: 50% profit target reached for {0}.".format(
                self._held_symbol
            )
        )

    def _evaluate_time_stop(self):
        if self._held_symbol is None:
            return

        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            return

        expiry = self._date_of(self._held_symbol.ID.Date)
        prior_trading_day = self._previous_trading_day(expiry)

        if self.Time.date() != prior_trading_day:
            return

        if self.Time.time() < time(15, 45):
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit()
        self._exit_ticket = self.MarketOrder(
            self._held_symbol, -quantity
        )
        self.Debug(
            "Exit submitted: expiration time stop for {0}.".format(
                self._held_symbol
            )
        )

    def _process_expiration_guard(self, current_date):
        if self._held_symbol is None:
            return

        expiry = self._date_of(self._held_symbol.ID.Date)
        if current_date < expiry:
            return

        self._no_entry_date = current_date

        if self.Portfolio[self._held_symbol].Invested:
            if self._exit_ticket is None or self._exit_ticket.Status.IsClosed():
                quantity = self.Portfolio[self._held_symbol].Quantity
                if quantity != 0:
                    self._exit_ticket = self.MarketOrder(
                        self._held_symbol, -quantity
                    )
                    self.Debug(
                        "Expiration guard exit submitted for {0}.".format(
                            self._held_symbol
                        )
                    )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def _cancel_open_exit(self):
        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self._exit_ticket.OrderId)
            self._exit_ticket = None

    def OnOrderEvent(self, order_event: OrderEvent):
        assignment_status = getattr(OrderStatus, "Assigned", None)
        exercise_status = getattr(OrderStatus, "Exercised", None)

        if (
            order_event.Status == assignment_status
            or order_event.Status == exercise_status
            or "assign" in str(order_event.Message).lower()
            or "exercis" in str(order_event.Message).lower()
        ):
            self.Debug(
                "Unexpected exercise or assignment handling: {0}".format(
                    order_event.Message
                )
            )

        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self._held_symbol = order_event.Symbol
                    self._entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entry filled: {0} at {1}.".format(
                            self._held_symbol, self._entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_,
                ):
                    self._entry_ticket = None

